#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Item {
    string nome;
    int peso;
    int quantidade;
};

int pesoTotal(const vector<Item>& mochila) {
    int total = 0;
    for (const auto& item : mochila) {
        total += item.peso * item.quantidade;
    }
    return total;
}

void guardar(vector<Item>& mochila, const Item& novo) {
    for (auto& item : mochila) {
        if (item.nome == novo.nome) {
            item.quantidade += novo.quantidade;
            return;
        }
    }
    mochila.push_back(novo);
}

int main() {
    vector<Item> mochila = {{"Pocao", 1, 3}};
    guardar(mochila, {"Espada", 5, 1});
    guardar(mochila, {"Pocao", 1, 2});
    for (const auto& item : mochila) {
        cout << item.nome << " x" << item.quantidade << endl;
    }
    cout << "Peso total: " << pesoTotal(mochila) << endl;
    return 0;
}

