#include <iostream>
using namespace std;

class Combo {
private:
    int atual = 0;
    int melhor = 0;

public:
    void acertou() {
        atual++;
        if (atual > melhor) {
            melhor = atual;
        }
    }
    void errou() {
        atual = 0;
    }
    int comboAtual() {
        return atual;
    }
    int melhorCombo() {
        return melhor;
    }
};

int main() {
    Combo c;
    c.acertou();
    c.acertou();
    c.acertou();
    c.errou();
    c.acertou();
    cout << "Combo atual: " << c.comboAtual() << endl;
    cout << "Melhor combo: " << c.melhorCombo() << endl;
    return 0;
}

