#include <iostream>
using namespace std;

class Audio {
private:
    int volume = 50;
    bool mudo = false;

public:
    int getVolume() const {
        return volume;
    }
    void setVolume(int novo) {
        if (novo < 0) {
            novo = 0;
        }
        if (novo > 100) {
            novo = 100;
        }
        volume = novo;
    }
    bool estaMudo() const {
        return mudo;
    }
    void alternarMudo() {
        mudo = !mudo;
    }
    int volumeEfetivo() const {
        return mudo ? 0 : volume;
    }
};

void mostrar(const Audio& a) {
    cout << "Volume: " << a.getVolume() << " | saindo: " << a.volumeEfetivo() << endl;
}

int main() {
    Audio a;
    mostrar(a);
    a.setVolume(130);
    mostrar(a);
    a.alternarMudo();
    mostrar(a);
    a.alternarMudo();
    mostrar(a);
    return 0;
}

