#include <iostream>
#include <string>
using namespace std;

class Personagem {
private:
    string nome;
    int vidaMaxima;   // declarada antes de vida: é criada primeiro
    int vida;

public:
    Personagem(string nome, int maximo) : nome(nome), vidaMaxima(maximo < 1 ? 1 : maximo), vida(vidaMaxima) {
    }
    int receberDano(int dano) {
        if (dano < 0) {
            dano = 0;
        }
        if (dano > vida) {
            dano = vida;
        }
        vida -= dano;
        return dano;
    }
    int curar(int quantidade) {
        if (quantidade < 0 || vida == 0) {
            return 0;
        }
        int falta = vidaMaxima - vida;
        if (quantidade > falta) {
            quantidade = falta;
        }
        vida += quantidade;
        return quantidade;
    }
    bool estaVivo() const {
        return vida > 0;
    }
    int getVida() const {
        return vida;
    }
    int getVidaMaxima() const {
        return vidaMaxima;
    }
    string getNome() const {
        return nome;
    }
};

int main() {
    Personagem p("Ana", 30);
    int tirou = p.receberDano(12);
    cout << "Tirou " << tirou << ", vida " << p.getVida() << endl;
    int curou = p.curar(50);
    cout << "Curou " << curou << ", vida " << p.getVida() << endl;
    tirou = p.receberDano(40);
    cout << "Tirou " << tirou << ", vida " << p.getVida() << endl;
    cout << boolalpha << "Vivo? " << p.estaVivo() << endl;
    return 0;
}

