#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Transacao {
    string tipo;
    int valor;
    int saldoDepois;
};

class Conta {
private:
    string titular;
    int saldo;
    vector<Transacao> extrato;

    void registrar(const string& tipo, int valor) {
        extrato.push_back({tipo, valor, saldo});
    }

public:
    Conta(string titular, int saldoInicial = 0) : titular(titular), saldo(saldoInicial < 0 ? 0 : saldoInicial) {
    }
    bool depositar(int valor) {
        if (valor <= 0) {
            return false;
        }
        saldo += valor;
        registrar("deposito", valor);
        return true;
    }
    bool sacar(int valor) {
        if (valor <= 0 || valor > saldo) {
            return false;
        }
        saldo -= valor;
        registrar("saque", valor);
        return true;
    }
    bool transferir(Conta& destino, int valor) {
        if (valor <= 0 || valor > saldo) {
            return false;
        }
        saldo -= valor;
        registrar("transferencia enviada", valor);
        destino.saldo += valor;
        destino.registrar("transferencia recebida", valor);
        return true;
    }
    int getSaldo() const {
        return saldo;
    }
    string getTitular() const {
        return titular;
    }
    const vector<Transacao>& getExtrato() const {
        return extrato;
    }
};

void mostrarExtrato(const Conta& c) {
    cout << "Extrato de " << c.getTitular() << " (saldo " << c.getSaldo() << "):" << endl;
    for (const auto& t : c.getExtrato()) {
        cout << "  " << t.tipo << " " << t.valor << " -> " << t.saldoDepois << endl;
    }
}

int main() {
    Conta ana("Ana", 100);
    Conta leo("Leo");
    ana.sacar(30);
    ana.sacar(500);
    ana.transferir(leo, 50);
    leo.depositar(-5);
    mostrarExtrato(ana);
    mostrarExtrato(leo);
    return 0;
}
